mapper.select:
SELECT referral.* FROM hr_employee_referral referral
WHERE referral.tenant_id = #{tenantId}
AND referral.referrer_employee_id = #{employeeId}
AND referral.status = #{query.status}
AND referral.candidate_name LIKE CONCAT('%', #{query.keyword}, '%')

    AND EXISTS (SELECT 1 FROM hr_employee employee WHERE employee.tenant_id = referral.tenant_id
        AND employee.id = referral.referrer_employee_id AND employee.deleted = 0

            AND employee.dept_id = #{scope.departmentId}

                AND employee.dept_id IN #{departmentId}

            AND 1 = 0
        )

ORDER BY referral.create_time DESC, referral.referral_id DESC

SELECT id AS value, CONCAT(requisition_no, ' · ', title) AS label FROM hr_recruitment_requisition WHERE tenant_id = #{tenantId} AND position_id = #{positionId} AND status = 'RECRUITING' AND deleted = 0 AND title LIKE CONCAT('%', #{query.keyword}, '%')
AND dept_id = #{scope.departmentId}
AND dept_id IN #{departmentId}
AND 1 = 0
ORDER BY id DESC
